     "            routeView: settings.routeView === 'list' ? 'list' : 'strip',\n            // Does the exported deck walk each diagram's steps, or stand at the\n            // whole picture the way it always did? Absent means walked: the deck\n            // is what the room saw, and the room saw the steps.\n            walk: settings.walk !== false\n          }",
